public class METDeleteDuplicateAddress extends RunBase
{
    DialogFIeld         fieldAccount;
    CustAccount         custAccount;
    CustTable           dcustTable;


}

Method.Source:
    Object Dialog()
    {

        Dialog dialog;
        dialog = super();

        // Set a title fordialog
        dialog.caption('NOTE: If NO Customer Account selected, all duplicate address across all entity will be deleted!');
        // Add a new field to Dialog
        fieldAccount =dialog.addField(extendedTypeStr(CustVendAC), 'Customer account' );

        return dialog;
    }

    public boolean getFromDialog()
    {
        // Retrieve values from Dialog
        custAccount =fieldAccount.value();

        return super();
    }

    public void run()
    {
        
        METDeleteDuplicateAddress deleteDuplicate = new METDeleteDuplicateAddress();
      
        //Set Dialog field value to find CustTable
        dcustTable = CustTable::find(custAccount);

        if (dcustTable)
        {
            deleteDuplicate.deleteRecordPercustomer(dcustTable);
        }
        else
        {
            deleteDuplicate.deleteAllRecords();
        }
    }

   /// <summary>
   ///Delete duplicate addresses
   /// </summary>
   public static void main(Args _args)
   {
       METDeleteDuplicateAddress deleteDuplicate = new METDeleteDuplicateAddress();
    
       DialogButton        diagBut;
     
    
       str strMessage = "Do you want to delete the records?";
       str strTitle = "Data deleted" ;

       diagBut = Box::yesNo(strMessage, DialogButton::No,  strTitle);
  
       if (diagBut == DialogButton::Yes)
       {
           if(deleteDuplicate.prompt())
            {
                deleteDuplicate.run();
            }         
       }
       else if(diagBut == DialogButton::No)
       {    
           info("Delete duplicate transactions has been cancelled.");
       }
   }

   public void deleteAllRecords()
   {
     

       Custtable                    Custtable,findCusttable,delCusttable;
       DirPartyLocation             DirPartyLocation;
       LogisticsLocation            LogisticsLocation,location,location2;
       LogisticsLocation            upLogisticsLocation;
       DirPartyPostalAddressView    DirPartyPostalAddressView,DirPartyPostalAddressView1,DirPartyPostalAddressView2,DirPartyPostalAddressView3;
       DirPartyPostalAddressView    delDirPartyPostalAddressView,delDirPartyPostalAddressView1;
       LogisticsPostalAddress       explocation;
       utcDateTime                  utcMinVal = DateTimeUtil::minValue();
       utcDateTime                  utcMaxVal = DateTimeUtil::maxValue();        
       str                          strMessage;
       container                    cont;
       str                          strAddress;
       CommaStreamIo                io = CommaStreamIo::constructForWrite();
       date                         currentDate = today();
       str                          cdate = date2Str(currentDate,
                                    321,
                                    DateDay::Digits2,
                                    DateSeparator::Hyphen,
                                    DateMonth::Digits2,
                                    DateSeparator::Hyphen,
                                    DateYear::Digits4);     
       METDeleteDuplicateAddress    deleteDuplicate = new METDeleteDuplicateAddress();
       str                         fileName = 'DeletedDuplicateAddress' + cdate + '.csv', fileContent;     
       
        // Write header
        io.writeExp(['DataAreaId', 'Customer', 'LocationName','Address','StreetNumber','Street','City','Zipcode','State','Country','CountyRegionID','Valid from','Valid to']);

        ttsbegin;
        //Delete Expired address
        while select  validTimeState(utcMinVal, utcMaxVal) delDirPartyPostalAddressView
        {
            deleteDuplicate.updateLocationID(delDirPartyPostalAddressView.Location);

            if(delDirPartyPostalAddressView.ValidTo != DateTimeUtil::maxValue())
            {              
                explocation =  LogisticsPostalAddress::findRecId(delDirPartyPostalAddressView.PostalAddress);
                if (explocation.aosValidateDelete())
                {
                    select crosscompany AccountNum,DataAreaId from  delCusttable where delCusttable.Party == delDirPartyPostalAddressView.Party;
                    // Write line
                    io.writeExp([delCusttable.DataAreaId,
                                 delCusttable.AccountNum,
                                 delDirPartyPostalAddressView.LOCATIONNAME,
                                 delDirPartyPostalAddressView.ADDRESS,
                                 delDirPartyPostalAddressView.STREETNUMBER,
                                 delDirPartyPostalAddressView.STREET,
                                 delDirPartyPostalAddressView.city,
                                 delDirPartyPostalAddressView.ZIPCODE,
                                 delDirPartyPostalAddressView.STATE,
                                 delDirPartyPostalAddressView.COUNTY,
                                 delDirPartyPostalAddressView.COUNTRYREGIONID,
                                 delDirPartyPostalAddressView.ValidFrom,
                                 delDirPartyPostalAddressView.ValidTo]);
                    explocation.selectForUpdate(true);
                    explocation.delete();
                }
            }
           
        }//end while


      
       //Group address by PARTY, LOCATIONNAME,ADDRESS,STREETNUMBER,STREET,city,ZIPCODE,STATE,COUNTY,COUNTRYREGIONID
       while select crosscompany DirPartyPostalAddressView
             group by PARTY, LOCATIONNAME,ADDRESS,STREETNUMBER,STREET,city,ZIPCODE,STATE,COUNTY,COUNTRYREGIONID
             join  DirPartyLocation
             where DirPartyPostalAddressView.PARTY ==DirPartyLocation.PARTY
                join custtable
                where custtable.Party == DirPartyLocation.Party
       {
        
           //Get the 1st transaction
           select firstonly RecId,IsPrimary,PARTY from DirPartyPostalAddressView1
                where DirPartyPostalAddressView1.LOCATIONNAME   == DirPartyPostalAddressView.LOCATIONNAME
                &&   DirPartyPostalAddressView1.ADDRESS         == DirPartyPostalAddressView.ADDRESS
                &&   DirPartyPostalAddressView1.STREETNUMBER    == DirPartyPostalAddressView.STREETNUMBER
                &&   DirPartyPostalAddressView1.STREET          == DirPartyPostalAddressView.STREET
                &&   DirPartyPostalAddressView1.city            == DirPartyPostalAddressView.city
                &&   DirPartyPostalAddressView1.ZIPCODE         == DirPartyPostalAddressView.ZIPCODE
                &&   DirPartyPostalAddressView1.STATE           == DirPartyPostalAddressView.STATE
                &&   DirPartyPostalAddressView1.COUNTY          == DirPartyPostalAddressView.COUNTY
                &&   DirPartyPostalAddressView1.COUNTRYREGIONID == DirPartyPostalAddressView.COUNTRYREGIONID
                &&   DirPartyPostalAddressView1.PARTY           == DirPartyPostalAddressView.PARTY;
          
           if(DirPartyPostalAddressView1.RecId != 0)
           {
                
               while select * from  DirPartyPostalAddressView2
                                where DirPartyPostalAddressView2.LOCATIONNAME    == DirPartyPostalAddressView.LOCATIONNAME
                                &&   DirPartyPostalAddressView2.ADDRESS         == DirPartyPostalAddressView.ADDRESS
                                &&   DirPartyPostalAddressView2.STREETNUMBER    == DirPartyPostalAddressView.STREETNUMBER
                                &&   DirPartyPostalAddressView2.STREET          == DirPartyPostalAddressView.STREET
                                &&   DirPartyPostalAddressView2.city            == DirPartyPostalAddressView.city
                                &&   DirPartyPostalAddressView2.ZIPCODE         == DirPartyPostalAddressView.ZIPCODE
                                &&   DirPartyPostalAddressView2.STATE           == DirPartyPostalAddressView.STATE
                                &&   DirPartyPostalAddressView2.COUNTY          == DirPartyPostalAddressView.COUNTY
                                &&   DirPartyPostalAddressView2.COUNTRYREGIONID == DirPartyPostalAddressView.COUNTRYREGIONID
                                &&   DirPartyPostalAddressView2.PARTY           == DirPartyPostalAddressView.PARTY
                                &&   DirPartyPostalAddressView2.RecId           != DirPartyPostalAddressView1.RecId
               {
                                                 
                   select crosscompany AccountNum,DataAreaId from  findCusttable where findCusttable.Party == DirPartyPostalAddressView.Party;
                   //validate if primary address else delete
                   if(DirPartyPostalAddressView2.IsPrimary == NoYes::Yes)
                   {  
                       while select * from  DirPartyPostalAddressView3
                                            where DirPartyPostalAddressView3.LOCATIONNAME    == DirPartyPostalAddressView.LOCATIONNAME
                                             &&   DirPartyPostalAddressView3.ADDRESS         == DirPartyPostalAddressView.ADDRESS
                                             &&   DirPartyPostalAddressView3.STREETNUMBER    == DirPartyPostalAddressView.STREETNUMBER
                                             &&   DirPartyPostalAddressView3.STREET          == DirPartyPostalAddressView.STREET
                                             &&   DirPartyPostalAddressView3.city            == DirPartyPostalAddressView.city
                                             &&   DirPartyPostalAddressView3.ZIPCODE         == DirPartyPostalAddressView.ZIPCODE
                                             &&   DirPartyPostalAddressView3.STATE           == DirPartyPostalAddressView.STATE
                                             &&   DirPartyPostalAddressView3.COUNTY          == DirPartyPostalAddressView.COUNTY
                                             &&   DirPartyPostalAddressView3.COUNTRYREGIONID == DirPartyPostalAddressView.COUNTRYREGIONID
                                             &&   DirPartyPostalAddressView3.PARTY           == DirPartyPostalAddressView.PARTY
                                             &&   DirPartyPostalAddressView3.IsPrimary        == NoYes::No
                       {
                                                       
                           location2 = LogisticsLocation::find(DirPartyPostalAddressView3.Location,true);
                           if (DirPartyPostalAddressView3.RecId != 0 && location2.validateDelete() && location2.aosValidateDelete())
                           {
                                // Write line
                                io.writeExp([findCusttable.DataAreaId,
                                            findCusttable.AccountNum,
                                            DirPartyPostalAddressView3.LOCATIONNAME,
                                            DirPartyPostalAddressView3.ADDRESS,
                                            DirPartyPostalAddressView3.STREETNUMBER,
                                            DirPartyPostalAddressView3.STREET,
                                            DirPartyPostalAddressView3.city,
                                            DirPartyPostalAddressView3.ZIPCODE,
                                            DirPartyPostalAddressView3.STATE,
                                            DirPartyPostalAddressView3.COUNTY,
                                            DirPartyPostalAddressView3.COUNTRYREGIONID,
                                            DirPartyPostalAddressView3.ValidFrom,
                                            DirPartyPostalAddressView3.ValidTo]);
        
                                location2.selectForUpdate(true);
                                location2.delete();
                           }
                               
                       }
                   }
                   else
                   {
                       location = LogisticsLocation::find(DirPartyPostalAddressView2.Location,true);
                       if (DirPartyPostalAddressView2.RecId != 0 && location.validateDelete())
                       {
                            // Write line
                            io.writeExp([findCusttable.DataAreaId,
                                            findCusttable.AccountNum,
                                            DirPartyPostalAddressView2.LOCATIONNAME,
                                            DirPartyPostalAddressView2.ADDRESS,
                                            DirPartyPostalAddressView2.STREETNUMBER,
                                            DirPartyPostalAddressView2.STREET,
                                            DirPartyPostalAddressView2.city,
                                            DirPartyPostalAddressView2.ZIPCODE,
                                            DirPartyPostalAddressView2.STATE,
                                            DirPartyPostalAddressView2.COUNTY,
                                            DirPartyPostalAddressView2.COUNTRYREGIONID,
                                            DirPartyPostalAddressView2.ValidFrom,
                                            DirPartyPostalAddressView2.ValidTo]);                            
                            location.delete();
                       }
                   }                   
               }
                
           }
           
        
       }  //end while
       
       ttscommit;
       info("All duplicate address successfully deleted!");
      
       // Set stream
       System.IO.Stream stream = io.getStream();
       stream.Position = 0;

       // Set stream reader
       System.IO.StreamReader sReader = new System.IO.StreamReader(stream);

       // Set file contentn string
       fileContent = sReader.ReadToEnd();

       // Save file
       File::SendStringAsFileToUser(fileContent, fileName);
     
            
   }

    public LogisticsLocation updateLocationID(LogisticsLocationRecId   _location)
   {
       LogisticsLocation logisticsLocation;

       while select forupdate logisticsLocation
           where logisticsLocation.RecId == _location
        {
            int len = strLen(logisticsLocation.locationid);
            str del;
            if(strFind(logisticsLocation.LocationId," ",1,len))
            {
                int fin = strFind(logisticsLocation.LocationId," ",1,len);
                del= strDel(logisticsLocation.LocationId,1,fin);
                logisticsLocation.LocationId = del;
                logisticsLocation.update();           
            }
        
        }
        return logisticsLocation;
   }

    public void deleteRecordPercustomer(CustTable _custtable)
    {
     

        Custtable                       Custtable,findCusttable,delCusttable,diaCusttable;
        DirPartyLocation                DirPartyLocation;
        LogisticsLocation               LogisticsLocation,location,location2;
        LogisticsLocation               upLogisticsLocation;
        DirPartyPostalAddressView       DirPartyPostalAddressView,DirPartyPostalAddressView1,DirPartyPostalAddressView2,DirPartyPostalAddressView3;
        DirPartyPostalAddressView       delDirPartyPostalAddressView,delDirPartyPostalAddressView1;
        LogisticsPostalAddress          explocation;
        utcDateTime                     utcMinVal = DateTimeUtil::minValue();
        utcDateTime                     utcMaxVal = DateTimeUtil::maxValue();        
        str                             strMessage;
        container                       cont;
        str                             strAddress;
        CommaStreamIo                   io = CommaStreamIo::constructForWrite();
        date                            currentDate = today();
        str                             cdate = date2Str(currentDate,
                                        321,
                                        DateDay::Digits2,
                                        DateSeparator::Hyphen,
                                        DateMonth::Digits2,
                                        DateSeparator::Hyphen,
                                        DateYear::Digits4);     
        METDeleteDuplicateAddress       deleteDuplicate = new METDeleteDuplicateAddress();
        str                             fileName = 'DeletedDuplicateAddress' + cdate + '.csv', fileContent;
     
        // Write header PARTY, LOCATIONNAME,ADDRESS,STREETNUMBER,STREET,city,ZIPCODE,STATE,COUNTY,COUNTRYREGIONID
        io.writeExp(['DataAreaId', 'Customer', 'LocationName','Address','StreetNumber','Street','City','Zipcode','State','Country','CountyRegionID','Valid from','Valid to']);
        
        select crosscompany Party from diaCusttable where diaCusttable.AccountNum == _custtable.AccountNum;
                 
        ttsbegin;
        //Delete Expired address
        while select  validTimeState(utcMinVal, utcMaxVal) delDirPartyPostalAddressView
         where   delDirPartyPostalAddressView.Party == diaCusttable.Party
        {

            deleteDuplicate.updateLocationID(delDirPartyPostalAddressView.Location);

            if(delDirPartyPostalAddressView.ValidTo != DateTimeUtil::maxValue())
            {
              
                explocation =  LogisticsPostalAddress::findRecId(delDirPartyPostalAddressView.PostalAddress);
                if (explocation.aosValidateDelete())
                {
                    select crosscompany AccountNum,DataAreaId from  delCusttable where delCusttable.Party == delDirPartyPostalAddressView.Party;
                    // Write line
                    io.writeExp([delCusttable.DataAreaId,
                                 delCusttable.AccountNum,
                                 delDirPartyPostalAddressView.LOCATIONNAME,
                                 delDirPartyPostalAddressView.ADDRESS,
                                 delDirPartyPostalAddressView.STREETNUMBER,
                                 delDirPartyPostalAddressView.STREET,
                                 delDirPartyPostalAddressView.city,
                                 delDirPartyPostalAddressView.ZIPCODE,
                                 delDirPartyPostalAddressView.STATE,
                                 delDirPartyPostalAddressView.COUNTY,
                                 delDirPartyPostalAddressView.COUNTRYREGIONID,
                                 delDirPartyPostalAddressView.ValidFrom,
                                 delDirPartyPostalAddressView.ValidTo]);
                    explocation.selectForUpdate(true);
                    explocation.delete();
                }
            }
           
        }
        //end while


      
        //Group address by PARTY, LOCATIONNAME,ADDRESS,STREETNUMBER,STREET,city,ZIPCODE,STATE,COUNTY,COUNTRYREGIONID
        while select crosscompany DirPartyPostalAddressView
             group by PARTY, LOCATIONNAME,ADDRESS,STREETNUMBER,STREET,city,ZIPCODE,STATE,COUNTY,COUNTRYREGIONID
             join  DirPartyLocation
             where DirPartyPostalAddressView.PARTY ==DirPartyLocation.PARTY
                join custtable
                where custtable.Party == DirPartyLocation.Party
               && DirPartyPostalAddressView.Party ==  diaCusttable.Party
        {
        
            //Get the 1st transaction
            select firstonly RecId,IsPrimary,PARTY from DirPartyPostalAddressView1
                where DirPartyPostalAddressView1.LOCATIONNAME   == DirPartyPostalAddressView.LOCATIONNAME
                &&   DirPartyPostalAddressView1.ADDRESS         == DirPartyPostalAddressView.ADDRESS
                &&   DirPartyPostalAddressView1.STREETNUMBER    == DirPartyPostalAddressView.STREETNUMBER
                &&   DirPartyPostalAddressView1.STREET          == DirPartyPostalAddressView.STREET
                &&   DirPartyPostalAddressView1.city            == DirPartyPostalAddressView.city
                &&   DirPartyPostalAddressView1.ZIPCODE         == DirPartyPostalAddressView.ZIPCODE
                &&   DirPartyPostalAddressView1.STATE           == DirPartyPostalAddressView.STATE
                &&   DirPartyPostalAddressView1.COUNTY          == DirPartyPostalAddressView.COUNTY
                &&   DirPartyPostalAddressView1.COUNTRYREGIONID == DirPartyPostalAddressView.COUNTRYREGIONID
                &&   DirPartyPostalAddressView1.PARTY           == DirPartyPostalAddressView.PARTY;
          
            if(DirPartyPostalAddressView1.RecId != 0)
            {
                
                while select * from  DirPartyPostalAddressView2
                                where DirPartyPostalAddressView2.LOCATIONNAME    == DirPartyPostalAddressView.LOCATIONNAME
                                &&   DirPartyPostalAddressView2.ADDRESS         == DirPartyPostalAddressView.ADDRESS
                                &&   DirPartyPostalAddressView2.STREETNUMBER    == DirPartyPostalAddressView.STREETNUMBER
                                &&   DirPartyPostalAddressView2.STREET          == DirPartyPostalAddressView.STREET
                                &&   DirPartyPostalAddressView2.city            == DirPartyPostalAddressView.city
                                &&   DirPartyPostalAddressView2.ZIPCODE         == DirPartyPostalAddressView.ZIPCODE
                                &&   DirPartyPostalAddressView2.STATE           == DirPartyPostalAddressView.STATE
                                &&   DirPartyPostalAddressView2.COUNTY          == DirPartyPostalAddressView.COUNTY
                                &&   DirPartyPostalAddressView2.COUNTRYREGIONID == DirPartyPostalAddressView.COUNTRYREGIONID
                                &&   DirPartyPostalAddressView2.PARTY           == DirPartyPostalAddressView.PARTY
                                &&   DirPartyPostalAddressView2.RecId           != DirPartyPostalAddressView1.RecId
                {
                               
                    select crosscompany AccountNum,DataAreaId from  findCusttable where findCusttable.Party == DirPartyPostalAddressView.Party;
                    //validate if primary address else delete
                    if(DirPartyPostalAddressView2.IsPrimary == NoYes::Yes)
                    {
                        while select * from  DirPartyPostalAddressView3
                                            where DirPartyPostalAddressView3.LOCATIONNAME    == DirPartyPostalAddressView.LOCATIONNAME
                                             &&   DirPartyPostalAddressView3.ADDRESS         == DirPartyPostalAddressView.ADDRESS
                                             &&   DirPartyPostalAddressView3.STREETNUMBER    == DirPartyPostalAddressView.STREETNUMBER
                                             &&   DirPartyPostalAddressView3.STREET          == DirPartyPostalAddressView.STREET
                                             &&   DirPartyPostalAddressView3.city            == DirPartyPostalAddressView.city
                                             &&   DirPartyPostalAddressView3.ZIPCODE         == DirPartyPostalAddressView.ZIPCODE
                                             &&   DirPartyPostalAddressView3.STATE           == DirPartyPostalAddressView.STATE
                                             &&   DirPartyPostalAddressView3.COUNTY          == DirPartyPostalAddressView.COUNTY
                                             &&   DirPartyPostalAddressView3.COUNTRYREGIONID == DirPartyPostalAddressView.COUNTRYREGIONID
                                             &&   DirPartyPostalAddressView3.PARTY           == DirPartyPostalAddressView.PARTY
                                             &&   DirPartyPostalAddressView3.IsPrimary        == NoYes::No
                        {
                                                       
                            location2 = LogisticsLocation::find(DirPartyPostalAddressView3.Location,true);
                            if (DirPartyPostalAddressView3.RecId != 0 && location2.validateDelete() && location2.aosValidateDelete())
                            {
                                // Write line
                                io.writeExp([findCusttable.DataAreaId,
                                            findCusttable.AccountNum,
                                            DirPartyPostalAddressView3.LOCATIONNAME,
                                            DirPartyPostalAddressView3.ADDRESS,
                                            DirPartyPostalAddressView3.STREETNUMBER,
                                            DirPartyPostalAddressView3.STREET,
                                            DirPartyPostalAddressView3.city,
                                            DirPartyPostalAddressView3.ZIPCODE,
                                            DirPartyPostalAddressView3.STATE,
                                            DirPartyPostalAddressView3.COUNTY,
                                            DirPartyPostalAddressView3.COUNTRYREGIONID,
                                            DirPartyPostalAddressView3.ValidFrom,
                                            DirPartyPostalAddressView3.ValidTo]);
        
                                location2.selectForUpdate(true);
                                location2.delete();
                            }
                               
                        }
                    }
                    else
                    {
                        location = LogisticsLocation::find(DirPartyPostalAddressView2.Location,true);
                        if (DirPartyPostalAddressView2.RecId != 0 && location.validateDelete())
                        {
                            // Write line
                            io.writeExp([findCusttable.DataAreaId,
                                            findCusttable.AccountNum,
                                            DirPartyPostalAddressView2.LOCATIONNAME,
                                            DirPartyPostalAddressView2.ADDRESS,
                                            DirPartyPostalAddressView2.STREETNUMBER,
                                            DirPartyPostalAddressView2.STREET,
                                            DirPartyPostalAddressView2.city,
                                            DirPartyPostalAddressView2.ZIPCODE,
                                            DirPartyPostalAddressView2.STATE,
                                            DirPartyPostalAddressView2.COUNTY,
                                            DirPartyPostalAddressView2.COUNTRYREGIONID,
                                            DirPartyPostalAddressView2.ValidFrom,
                                            DirPartyPostalAddressView2.ValidTo]);
                            location.delete();
                        }
                    }                   
                }                
            }       
        
        }
        //end while
       
        ttscommit;
        info("Duplicate address successfully deleted!");
      
        // Set stream
        System.IO.Stream stream = io.getStream();
        stream.Position = 0;

        // Set stream reader
        System.IO.StreamReader sReader = new System.IO.StreamReader(stream);

        // Set file contentn string
        fileContent = sReader.ReadToEnd();

        // Save file
        File::SendStringAsFileToUser(fileContent, fileName);
     
            
    }
